<?php
// Senast uppdaterad 2026-10-12 10:00 (Asia/Bangkok)
declare(strict_types=1);
if (!isset($user,$app,$csrf) || !$user) { http_response_code(404); exit; }
$month=(string)($_GET['month']??(new DateTimeImmutable('now',new DateTimeZone('Asia/Bangkok')))->format('Y-m'));
if (!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month)) $month=(new DateTimeImmutable('now',new DateTimeZone('Asia/Bangkok')))->format('Y-m');
$first=new DateTimeImmutable($month.'-01',new DateTimeZone('Asia/Bangkok'));
$next=$first->modify('+1 month');
$stmt=$app->db->prepare("SELECT check_in,check_out,status,expires_at FROM bookings WHERE check_in < ? AND check_out > ? AND status IN ('inquiry','hold','confirmed')");
$stmt->execute([$next->format('Y-m-d'),$first->format('Y-m-d')]);$calendarBookings=$stmt->fetchAll();
$stmt=$app->db->prepare('SELECT check_in,check_out FROM availability_blocks WHERE active=1 AND check_in < ? AND check_out > ?');
$stmt->execute([$next->format('Y-m-d'),$first->format('Y-m-d')]);$calendarBlocks=$stmt->fetchAll();
?>
<section id="month"><h2>Månadskalender</h2><p><a href="<?=ae(url('admin.php').'?month='.$first->modify('-1 month')->format('Y-m'))?>#month">← Föregående</a> · <?=ae($first->format('F Y'))?> · <a href="<?=ae(url('admin.php').'?month='.$next->format('Y-m'))?>#month">Nästa →</a></p><div class="admin-calendar" style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px;"><?php foreach(['M','T','O','T','F','L','S'] as $weekday):?><strong><?=ae($weekday)?></strong><?php endforeach;?><?php for($i=1;$i<(int)$first->format('N');$i++):?><span></span><?php endfor;?><?php for($day=$first;$day<$next;$day=$day->modify('+1 day')): $date=$day->format('Y-m-d');$state='Ledigt';$pending=0;foreach($calendarBlocks as $block)if($block['check_in']<=$date&&$block['check_out']>$date)$state='Blockerat';foreach($calendarBookings as $booking){if($booking['check_in']<=$date&&$booking['check_out']>$date){if($booking['status']==='confirmed')$state='Bokat';elseif($booking['status']==='hold'&&$booking['expires_at']>gmdate('Y-m-d H:i:s'))$state='Reservation';elseif($booking['status']==='inquiry')$pending++;}}?><div style="min-height:58px;border:1px solid #e2e2db;border-radius:6px;padding:4px;background:<?=$state==='Ledigt'?'#fffefa':'#eaece5'?>" aria-label="<?=ae($date.' '.$state)?>"><strong><?=ae($day->format('j'))?></strong><small style="display:block"><?=ae($state)?></small><?php if($pending):?><small><?=$pending?> förfr.</small><?php endif;?></div><?php endfor;?></div><p>Ledigt · Bokat · Reservation · Blockerat. Väntande förfrågningar spärrar inte datum.</p></section>
<?php
$simDate=(string)($_GET['sim_date']??(new DateTimeImmutable('today',new DateTimeZone('Asia/Bangkok')))->modify('+30 days')->format('Y-m-d'));
$simGuests=(int)($_GET['sim_guests']??1);
$simStart=DateTimeImmutable::createFromFormat('!Y-m-d',$simDate,new DateTimeZone('Asia/Bangkok'));
if (!$simStart || $simStart->format('Y-m-d')!==$simDate) $simStart=null;
?>
<section id="simulate"><h2>Prissimulator</h2><p>Jämför prisregler innan du använder dem. Resultatet är en intern kalkyl, ingen gästoffert.</p><form method="get"><label>Startdatum <input type="date" name="sim_date" value="<?=ae($simDate)?>" required></label><label>Gäster <input type="number" name="sim_guests" min="1" value="<?=ae($simGuests)?>" required></label><button>Räkna</button></form><div class="scroll"><table><tr><th>Nätter</th><th>Summa</th><th>Kommentar</th></tr><?php foreach([1,3,7,14,28,30] as $nights):?><tr><td><?=$nights?></td><?php try { if(!$simStart)throw new RuntimeException('Ogiltigt startdatum.');$result=$app->price($simDate,$simStart->modify('+'.$nights.' days')->format('Y-m-d'),$simGuests); ?><td><?=number_format($result['totalSatang']/100,2,',',' ')?> THB</td><td><?=count($result['discounts'])?> rabatt(er)</td><?php } catch(Throwable $error) { ?><td colspan="2">Ej tillgängligt eller pris ej godkänt</td><?php } ?></tr><?php endforeach;?></table></div></section>
